1	/**
2	 * เส้นทาง API ทั้งหมด
3	 *
4	 * ดูสัญญาฉบับเต็มที่ openapi.yaml และข้อกำหนดที่ REQUIREMENTS.md
5	 */
6	
7	import { Router, type Ctx } from './router.ts';
8	import { loadEvents, appendEvents } from '../store/eventStore.ts';
9	import {
10	  createBooking, approveBooking, rejectBooking, startBooking, completeBooking,
11	  replay, replayAll, DomainError, type BookingState,
12	} from '../domain/booking.ts';
13	import type { Role } from '../domain/events.ts';
14	import { RESOURCES } from '../domain/policy.ts';
15	import { occupiedSlots } from '../projections/availability.ts';
16	import { buildInvoice } from '../projections/billing.ts';
17	import { nowIso } from '../lib/clock.ts';
18	
19	export const router = new Router();
20	
21	let counter = 0;
22	function nextBookingId(): string {
23	  counter += 1;
24	  return `bk-${Date.now().toString(36)}-${counter}`;
25	}
26	
27	function requireBooking(bookingId: string): { state: BookingState; events: ReturnType<typeof loadEvents> } {
28	  const events = loadEvents();
29	  const state = replay(events.filter((e) => e.bookingId === bookingId));
30	  if (!state) throw new DomainError('BOOKING_NOT_FOUND', `ไม่พบการจอง ${bookingId}`, 404);
31	  return { state, events };
32	}
33	
34	function actor(ctx: Ctx): { id: string; role: Role } {
35	  return { id: ctx.userId, role: ctx.userRole as Role };
36	}
37	
38	// ---------------------------------------------------------------- bookings
39	
40	router.add('POST', '/bookings', (ctx) => {
41	  const me = actor(ctx);
42	  const body = ctx.body ?? {};
43	  const events = loadEvents();
44	
45	  const newEvents = createBooking(
46	    {
47	      bookingId: nextBookingId(),
48	      userId: me.id,
49	      userRole: me.role,
50	      resourceId: body.resourceId,
51	      startAt: body.startAt,
52	      endAt: body.endAt,
53	    },
54	    replayAll(events),
55	  );
56	  appendEvents(newEvents);
57	
58	  // TODO: send notification on status change
59	  // ทีมงานเคยคุยกันว่าอยากให้มีการแจ้งเตือนเวลาสถานะเปลี่ยน แต่ยังไม่ได้ข้อสรุปว่า
60	  // จะส่งทางอีเมลหรือทาง LINE และใครควรได้รับบ้าง จึงยังไม่ได้ทำ
61	
62	  return { status: 201, payload: replay(newEvents) };
63	});
64	
65	router.add('GET', '/bookings', (ctx) => {
66	  let list = replayAll(loadEvents());
67	  const userId = ctx.query.get('userId');
68	  const resourceId = ctx.query.get('resourceId');
69	  const status = ctx.query.get('status');
70	  const from = ctx.query.get('from');
71	  const to = ctx.query.get('to');
72	
73	  if (userId) list = list.filter((b) => b.userId === userId);
74	  if (resourceId) list = list.filter((b) => b.resourceId === resourceId);
75	  if (status) list = list.filter((b) => b.status === status);
76	  if (from) list = list.filter((b) => b.endAt >= from);
77	  if (to) list = list.filter((b) => b.startAt <= to);
78	
79	  return list.sort((a, b) => a.startAt.localeCompare(b.startAt));
80	});
81	
82	router.add('GET', '/bookings/:bookingId', (ctx) => {
83	  return requireBooking(ctx.params.bookingId).state;
84	});
85	
86	router.add('POST', '/bookings/:bookingId/approve', (ctx) => {
